using System;
using System.Collections.Generic;
using System.Linq;
using BepInEx.Configuration;
using Comfort.Common;
using EFT;
using EFT.Ballistics;
using HarmonyLib;
using UnityEngine;
namespace LocalSpt5Esp;
internal static class BulletTrajectories {
 sealed class Trace {internal Shot? Shot;internal int Fire,Seed,Fragment;internal IntPtr Pointer;internal float Finished,Next;internal readonly TrajectoryPath Path=new();}
 static ConfigEntry<bool> enabled=null!;static ConfigEntry<float> lifetime=null!,width=null!;static ConfigEntry<string> color=null!;static readonly List<Trace> traces=new();static readonly Dictionary<IntPtr,Trace> active=new();static IntPtr world;static float nextError;
 internal static void Initialize(Plugin plugin){enabled=FeatureConfig.Bind("40. 弹道与伤害预览","Bullet trails","显示玩家子弹轨迹",true,"记录玩家实际发射的子弹路径。最多保留 64 条，每条最多 48 个轨迹点。");lifetime=FeatureConfig.Bind("40. 弹道与伤害预览","Trail lifetime","弹道保留秒数",2.5f,"命中后保留的时间。",new AcceptableValueRange<float>(0,15));width=FeatureConfig.Bind("40. 弹道与伤害预览","Trail width","弹道线条宽度",1.5f,"",new AcceptableValueRange<float>(1,8));color=FeatureConfig.Bind("40. 弹道与伤害预览","Trail color","弹道颜色（十六进制）","#FFCB6B");try{foreach(var method in typeof(BallisticsCalculator).GetMethods().Where(m=>m.Name=="Shoot"&&m.DeclaringType==typeof(BallisticsCalculator)))plugin.Patches.Patch(method,prefix:new HarmonyMethod(typeof(BulletTrajectories),nameof(Started)));plugin.Patches.Patch(AccessTools.Method(typeof(Shot),"ReturnShotToPool"),prefix:new HarmonyMethod(typeof(BulletTrajectories),nameof(Returning)));plugin.Log.LogInfo("Bullet trajectory capture ready: local shots, pooled-shot final capture, bounded paths");}catch(Exception e){plugin.Log.LogError("Bullet trajectory hooks: "+e);}}
 internal static void Reset(){traces.Clear();active.Clear();world=IntPtr.Zero;}
 static bool Same(Trace trace,Shot shot)=>shot.Pointer==trace.Pointer&&shot.FireIndex==trace.Fire&&shot.RandomSeed==trace.Seed&&shot.FragmentIndex==trace.Fragment;
 static void Started(Shot __0){if(!enabled.Value||!RaidClock.Active||__0==null)return;try{var current=Singleton<GameWorld>.Instance;var player=current?.MainPlayer;if(player==null||__0.PlayerRaidId!=player.RaidId)return;if(world!=current!.Pointer){Reset();world=current.Pointer;}if(active.TryGetValue(__0.Pointer,out var prior)){if(Same(prior,__0))return;Finish(prior);}while(traces.Count>=64){var oldest=traces[0];if(active.TryGetValue(oldest.Pointer,out var cached)&&ReferenceEquals(cached,oldest))active.Remove(oldest.Pointer);traces.RemoveAt(0);}var trace=new Trace{Shot=__0,Pointer=__0.Pointer,Fire=__0.FireIndex,Seed=__0.RandomSeed,Fragment=__0.FragmentIndex};traces.Add(trace);active[trace.Pointer]=trace;Append(trace,__0.MasterOrigin);Append(trace,__0.CurrentPosition);}catch(Exception e){Warn(e);}}
 static void Append(Trace trace,Vector3 point)=>trace.Path.Add(new(point.x,point.y,point.z));
 static void Capture(Trace trace,Shot shot,bool final){if(final){var history=shot.PositionHistory;if(history!=null){int length=history.Count;if(length>=2)trace.Path.Points.Clear();int stride=Math.Max(1,length/192);for(int i=0;i<length;i+=stride)Append(trace,history[i]);}}Append(trace,shot.CurrentPosition);}
 static void Finish(Trace trace){trace.Shot=null;trace.Finished=Time.unscaledTime;active.Remove(trace.Pointer);}
 static void Returning(Shot __0){if(!enabled.Value||__0==null||!active.TryGetValue(__0.Pointer,out var trace))return;try{if(Same(trace,__0))Capture(trace,__0,true);Finish(trace);}catch(Exception e){Finish(trace);Warn(e);}}
 internal static void Tick(GameWorld? current){if(!enabled.Value||current==null||!RaidClock.Active){if(traces.Count>0)Reset();return;}if(world!=IntPtr.Zero&&world!=current.Pointer){Reset();return;}float now=Time.unscaledTime;foreach(var trace in traces){if(trace.Shot==null||now<trace.Next)continue;trace.Next=now+.025f;try{var shot=trace.Shot;if(!Same(trace,shot)){Finish(trace);continue;}Capture(trace,shot,false);if(shot.IsShotFinished){Capture(trace,shot,true);Finish(trace);}}catch(Exception e){Finish(trace);Warn(e);}}traces.RemoveAll(trace=>trace.Shot==null&&now-trace.Finished>lifetime.Value);}
 internal static void Draw(Camera camera){if(!enabled.Value||Event.current.type!=EventType.Repaint)return;Color tint=ColorUtility.TryParseHtmlString(color.Value,out var chosen)?chosen:new Color(1,.8f,.42f);int budget=1536;for(int i=traces.Count-1;i>=0&&budget>0;i--){var trace=traces[i];float fade=trace.Shot!=null?1:Math.Clamp(1-(Time.unscaledTime-trace.Finished)/Math.Max(.001f,lifetime.Value),0,1);tint.a=fade;var path=trace.Path.Points;for(int p=1;p<path.Count&&budget-->0;p++){var a=path[p-1];var b=path[p];Vector3 wa=new(a.X,a.Y,a.Z),wb=new(b.X,b.Y,b.Z);var sa=camera.WorldToScreenPoint(wa);var sb=camera.WorldToScreenPoint(wb);if(!float.IsFinite(sa.x)||!float.IsFinite(sa.y)||!float.IsFinite(sa.z)||!float.IsFinite(sb.x)||!float.IsFinite(sb.y)||!float.IsFinite(sb.z))continue;const float near=.05f;if(sa.z<near&&sb.z<near)continue;if(sa.z<near){wa=Vector3.Lerp(wa,wb,(near-sa.z)/(sb.z-sa.z));sa=camera.WorldToScreenPoint(wa);}else if(sb.z<near){wb=Vector3.Lerp(wb,wa,(near-sb.z)/(sa.z-sb.z));sb=camera.WorldToScreenPoint(wb);}RaidLoot.Line(new(sa.x,Screen.height-sa.y),new(sb.x,Screen.height-sb.y),tint,width.Value);}}}
 static void Warn(Exception e){if(Time.unscaledTime<nextError)return;nextError=Time.unscaledTime+20;Plugin.Self.Log.LogWarning("Bullet trajectories: "+e.Message);}
}
